function tree(t,ds,errs,path="filters"){if(!is(t)){errs.push(path+" باید object باشد.");return null;}const logic=t.logic??"and",cs=t.conditions??[],gs=t.groups??[];if(!C.filterLogics.includes(logic)||!Array.isArray(cs)||!Array.isArray(gs)){errs.push(path+" ساختار نامعتبر دارد.");return null;}if(!cs.length&&!gs.length)errs.push(path+" خالی است.");const conditions=[];for(let i=0;i<cs.length;i++){const x=cs[i],l=path+".conditions["+i+"]";if(!is(x)){errs.push(l+" باید object باشد.");continue;}const f=ds.fields[x.field],op=x.operator;if(!f||!f.roles.includes("filter")){errs.push(l+" فیلد نامعتبر: "+x.field);continue;}if(!(C.operators[f.type]??[]).includes(op)){errs.push(l+" عملگر نامعتبر: "+op);continue;}const no=["exists","not_exists"].includes(op),arr=["in","not_in","between"].includes(op);let vs=[];if(no){if(x.value!=null)errs.push(l+" نباید value داشته باشد.");}else if(arr){if(!Array.isArray(x.value)||!x.value.length||(op==="between"&&x.value.length!==2)){errs.push(l+" آرایه value نامعتبر است.");continue;}vs=x.value;}else{if(x.value==null||Array.isArray(x.value)){errs.push(l+" value لازم است.");continue;}vs=[x.value];}const nv=[];for(const v of vs){if(f.type==="number"){const n=Number(v);if(typeof v==="boolean"||v===""||!Number.isFinite(n))errs.push(l+" مقدار عددی نامعتبر است.");else nv.push(n);}else if(f.type==="boolean"){if(typeof v!=="boolean")errs.push(l+" باید boolean باشد.");else nv.push(v);}else if(["string","number"].includes(typeof v)&&String(v).trim())nv.push(String(v).trim());else errs.push(l+" مقدار متنی نامعتبر است.");}if(op==="between"&&nv.length===2&&nv[0]>nv[1])errs.push(l+" بازه نامعتبر است.");conditions.push({field:x.field,operator:op,...(no?{}:{value:arr?nv:nv[0]})});}const groups=gs.map((g,i)=>tree(g,ds,errs,path+".groups["+i+"]")).filter(Boolean);return {logic,conditions,groups};}
