if(op==="select"&&(groups.length||metrics.length))e.push("select بدون group_by/metrics است.");if(op==="count"&&(groups.length||metrics.length||ss.length||a.limit!=null))e.push("count بدون group_by/metrics/sort/limit است.");if(op==="aggregate"&&!metrics.length)e.push("aggregate به حداقل یک metric نیاز دارد.");
