// Prepare LLM Context
// Version: 2.1
// Mode: Run Once for All Items

const items = $input.all().map(item => item.json);

if (items.length === 0) {
  throw new Error(
    "Prepare LLM Context: ورودی Format Result خالی است."
  );
}

// Safely parse JSON values.
function parseJson(value, fieldName) {
  if (value === undefined || value === null || value === "") {
    return null;
  }

  if (typeof value !== "string") {
    return value;
  }

  try {
    return JSON.parse(value);
  } catch (error) {
    return {
      parse_error: true,
      field: fieldName,
      raw_value: value
    };
  }
}

// Return the first valid non-negative numeric value.
function getNumericValue(...values) {
  for (const value of values) {
    if (
      value !== undefined &&
      value !== null &&
      value !== "" &&
      Number.isFinite(Number(value)) &&
      Number(value) >= 0
    ) {
      return Number(value);
    }
  }

  return null;
}

// Validate the user's question.
const questions = [
  ...new Set(
    items
      .map(item => String(item.question ?? "").trim())
      .filter(Boolean)
  )
];

if (questions.length === 0) {
  throw new Error(
    "Prepare LLM Context: متن سؤال کاربر پیدا نشد."
  );
}

if (questions.length > 1) {
  throw new Error(
    "Prepare LLM Context: چند سؤال متفاوت در ورودی دریافت شد."
  );
}

const question = questions[0];
const responseMode = items[0].responseMode ?? "combined";
const request = $("Prepare Input").first()?.json ?? {};
const language = request.language ?? "und";
const includeAnalysis = request.includeAnalysis === true;
const sessionId = request.sessionId ?? null;
const chatSessionIds = [...new Set(items.map(item => String(item.chatSessionId ?? "").trim()).filter(Boolean))];
if (chatSessionIds.length > 1) {
  throw new Error("Prepare LLM Context: mixed chat sessions detected in one execution.");
}
if (sessionId && chatSessionIds.length === 1 && chatSessionIds[0] !== sessionId) {
  throw new Error("Prepare LLM Context: chat session identity mismatch.");
}
const mcpSessionIds = [...new Set(items.map(item => String(item.mcpSessionId ?? "").trim()).filter(Boolean))];
if (mcpSessionIds.length > 1) {
  throw new Error("Prepare LLM Context: mixed MCP sessions detected in one execution.");
}
const expectedMcpSessionId = $("MCP Parse Init").first()?.json?.sessionId ?? null;
if (expectedMcpSessionId && mcpSessionIds.length === 1 && mcpSessionIds[0] !== expectedMcpSessionId) {
  throw new Error("Prepare LLM Context: MCP session identity mismatch.");
}
const mcpSessionId = mcpSessionIds[0] ?? expectedMcpSessionId;

// Normalize each MCP plan independently.
const results = items.map((item, index) => {

  const parsedFacts = parseJson(
    item.factsJson ?? item.facts,
    "factsJson"
  );

  const executedQuery = parseJson(
    item.queryJson ?? item.executedQuery,
    "queryJson"
  );

  const facts =
    parsedFacts &&
    typeof parsedFacts === "object" &&
    !Array.isArray(parsedFacts)
      ? parsedFacts
      : null;

  // Execution status is independent of plan recognition.
  let executionStatus = "unknown";

  if (typeof item.executionSuccess === "boolean") {
    executionStatus = item.executionSuccess
      ? "success"
      : "failure";
  } else if (typeof item.success === "boolean") {
    executionStatus = item.success
      ? "success"
      : "failure";
  } else if (item.error) {
    executionStatus = "failure";
  }

  // Full structured records must be supplied by Format Result
  // under facts.rows.
  const fullRows = Array.isArray(facts?.rows)
    ? facts.rows
    : null;

  // rows_sample is only a preview, not a replacement for rows.
  const sampleRows = Array.isArray(facts?.rows_sample)
    ? facts.rows_sample
    : [];

  const expectedRecords = getNumericValue(
    item.totalRecords,
    facts?.total_records,
    item.rowCount,
    facts?.row_count,
    item.shown,
    facts?.shown
  );

  const availableRecords = fullRows
    ? fullRows.length
    : sampleRows.length;

  // COUNT is a scalar; AGGREGATE rows are buckets. Neither is a
  // document sample and neither can establish source-index completeness.
  let completenessStatus = "not_applicable";
  let responseLimited = false;

  if (item.operation === "select") {
    if (fullRows !== null) {
      if (expectedRecords === null) {
        completenessStatus = "available_unverified";
      } else if (fullRows.length >= expectedRecords) {
        completenessStatus = "complete";
      } else {
        completenessStatus = "partial_response";
        responseLimited = true;
      }
    } else if (sampleRows.length > 0) {
      completenessStatus = "sample_only";
      responseLimited = true;
    } else {
      completenessStatus = "unknown";
    }
  }

  return {
    result_index: index + 1,

    tool: item.selectedTool ?? "unknown",
    operation: item.operation ?? null,

    plan_status: {
      recognized: item.recognized === true,
      execution_status: executionStatus,
      error: item.error ?? null
    },

    data_statistics: {
      row_count: getNumericValue(
        item.rowCount,
        facts?.row_count
      ),

      total_records: getNumericValue(
        item.totalRecords,
        facts?.total_records
      ),

      shown: getNumericValue(
        item.shown,
        facts?.shown
      ),

      count_value: item.countValue ?? facts?.count ?? null
    },

    record_semantics:
      item.operation === "count"
        ? "scalar_count"
        : item.operation === "aggregate"
          ? "aggregation_buckets"
          : item.operation === "select"
            ? "selected_documents"
            : "tool_specific",

    data_completeness: {
      status: completenessStatus,
      expected_records: expectedRecords,
      available_records: availableRecords,
      structured_rows_available: fullRows !== null,
      response_limited: responseLimited,
      dataset_completeness: "not_assessed",
      is_complete: completenessStatus === "complete" ? true : null
    },

    // Preserve all original facts.
    // Full records are expected in facts.rows.
    facts: facts ?? parsedFacts,

    executed_query: executedQuery,

    display_reference: {
      table_markdown: item.tableMarkdown ?? ""
    }
  };
});

// Calculate context-level statistics.
const recognizedPlans = results.filter(
  result => result.plan_status.recognized
