const successfulExecutions = results.filter(
  result => result.plan_status.execution_status === "success"
).length;

const failedExecutions = results.filter(
  result => result.plan_status.execution_status === "failure"
).length;

const unknownExecutions = results.filter(
  result => result.plan_status.execution_status === "unknown"
).length;

const completeResults = results.filter(
  result => result.data_completeness.status === "complete"
).length;

const limitedResults = results.filter(
  result => result.data_completeness.response_limited === true
).length;

// Build unified analytical context.
const context = {
  context_version: "2.1",

  question,
  response_mode: responseMode,
  response_language: language,
  session_id: sessionId,
  mcp_session_id: mcpSessionId,

  metadata: {
    total_plans: results.length,

    recognized_plans: recognizedPlans,
    unrecognized_plans: results.length - recognizedPlans,

    successful_executions: successfulExecutions,
    failed_executions: failedExecutions,
    unknown_executions: unknownExecutions,

    complete_results: completeResults,
    limited_results: limitedResults,
    incomplete_results: 0
  },

  analytical_instructions: {
    source_of_truth: "MCP tool results",

    rules: [
      "Use only the supplied MCP results.",
      "Analyze all available plans.",
      "Compare related results across tools when relevant to the user's question.",
      "Distinguish observed facts from analytical inferences.",
      "Do not invent missing values or records.",
      "Do not treat unknown execution status as success.",
      "Identify incomplete or failed results.",
      "Use executed queries to understand result scope.",
      "Use facts.rows as the authoritative structured record collection.",
      "Never treat rows_sample as the complete dataset.",
      "COUNT values are scalar summaries; never compare their one-row representation with source document totals.",
      "AGGREGATE rows are buckets; never compare bucket count with source document totals to infer dataset completeness.",
      "A limited SELECT response is not proof that the underlying dataset is incomplete.",
      "Dataset completeness is not assessed by this workflow.",
      "Do not infer that missing sample records do not exist.",
      "Do not reproduce complete tables unless requested by the user."
    ]
  },

  results
};

// Preserve downstream compatibility.
const serializedContext = JSON.stringify(context, null, 2);

return [
  {
    json: {
      question,
      responseMode,
      language,
      includeAnalysis,
      sessionId,
      mcpSessionId,

      recognized:
        recognizedPlans === results.length,

      totalPlans: results.length,

      successfulExecutions,
      failedExecutions,
      unknownExecutions,

      factsJson: serializedContext,
      contextJson: serializedContext
    }
  }
];

const response = $input.first()?.json ?? {};
const statusCode = Number(response.statusCode ?? 0);
const accepted = Number.isInteger(statusCode) && statusCode >= 200 && statusCode < 300;
const body = String(response.body ?? response.data ?? "").trim().slice(0, 1000);
const error = accepted ? null : `MCP initialized notification failed (HTTP ${statusCode || "unknown"}). ${body}`.trim();
return [{ json: { ok: accepted, statusCode, error } }];
